using System.Net;
using System.Text.Json;
using Htt.Host.Api.Accounting;
using Htt.Host.Api.MasterData;
using Htt.Host.Api.Purchasing;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class CashFlowTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT to_char((now() AT TIME ZONE timezone)::date,'YYYY-MM-DD') FROM core.companies WHERE id=@company",("company",db.Company)))!);
 private static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();
 private static decimal T(JsonElement e,string field)=>D(e.GetProperty("totals").GetProperty(field));
 private async Task<JsonElement> Report(HttpClient c,DateOnly? from=null,DateOnly? to=null,string suffix="")=>await Get(c,$"/accounting/reports/cash-flow?from={from??await Today():yyyy-MM-dd}&to={to??(await Today()).AddDays(1):yyyy-MM-dd}{suffix}");
 private static decimal Activity(JsonElement r,string category,string field)=>r.GetProperty("activities").EnumerateArray().Where(x=>x.GetProperty("category").GetString()==category).Select(x=>D(x.GetProperty(field))).SingleOrDefault();
 private static Task<JsonElement> Detail(HttpClient c,Guid id)=>Get(c,$"/accounting/cash-flow/journals/{id}");
 private static Task<HttpResponseMessage> Classify(HttpClient c,Guid journal,CashFlowAllocation[]items,long version=0,string? key=null,string mode="CUSTOM")=>Send(c,HttpMethod.Put,$"/accounting/cash-flow/journals/{journal}/classification",new CashFlowClassificationInput(mode,"Reviewed source and GST classification",items),version,key);
 private async Task<Guid> Bank(HttpClient c,string kind="CASH")=>await Create(c,"/bank-accounts",kind=="BANK"?new BankAccountInput(Code(),"Cash-flow bank",kind,"062000",Random.Shared.NextInt64(100000,9999999999999).ToString(System.Globalization.CultureInfo.InvariantCulture),"HTT Flooring"):new BankAccountInput(Code(),"Cash-flow account",kind));
 private async Task<Guid> Account(string kind="ASSET")=>(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind) VALUES(@company,@code,'Cash-flow contra',@kind) RETURNING id",("company",db.Company),("code",Code()),("kind",kind)))!;
 private sealed record Leg(Guid Account,decimal Debit=0,decimal Credit=0);
 private async Task<(Guid Journal,Guid[] Lines)> Journal(Leg[]legs,DateOnly? date=null)
 {
  var dt=date??await Today();var doc=(Guid)(await S("INSERT INTO platform.documents(company_id,document_type,business_date,created_by) VALUES(@company,'CASH_FLOW_TEST',@date,@actor) RETURNING id",("company",db.Company),("date",dt),("actor",db.Actor)))!;
  await using var session=await db.SessionAsync();var json=JsonSerializer.Serialize(legs.Select(x=>new{accountId=x.Account,debit=x.Debit,credit=x.Credit}));var rows=await Sql.RowsAsync(session,"SELECT accounting.post_journal(@doc,1,'CASH_FLOW_TEST',@date,'Cash flow test',@items::jsonb) AS id",default,("doc",doc),("date",dt),("items",json));var journal=(Guid)rows[0]["id"]!;var lines=await Sql.RowsAsync(session,"SELECT id FROM accounting.journal_lines WHERE company_id=core.current_company() AND journal_entry_id=@id ORDER BY id",default,("id",journal));await session.Transaction.CommitAsync();return(journal,lines.Select(x=>(Guid)x["id"]!).ToArray());
 }
 private async Task<(Guid Payment,Guid Journal,Guid Cash,Guid Supplier)> Pay(HttpClient c,Guid? bank=null,decimal amount=100,DateOnly? date=null)
 {
  var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Cash-flow supplier",null));var response=await Expect(await Send(c,HttpMethod.Post,$"/suppliers/{supplier}/payments",new SupplierPaymentInput(amount,"BANK_TRANSFER",Code(),amount,PaidOn:date,Notes:"Trade prepayment",BankAccountId:bank)),HttpStatusCode.Created);var pid=response.GetProperty("payment").GetProperty("id").GetGuid();var j=(Guid)(await S("SELECT journal_entry_id FROM accounting.supplier_payments WHERE company_id=@company AND id=@id",("company",db.Company),("id",pid)))!;var cash=(Guid)(await S("SELECT l.id FROM accounting.journal_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=@company AND l.journal_entry_id=@id AND a.control_kind='BANK'",("company",db.Company),("id",j)))!;return(pid,j,cash,supplier);
 }
 [Fact] public async Task Empty_cash_flow_is_exact_and_does_not_claim_external_bank_reconciliation()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var r=await Report(c);Assert.Equal("READY",r.GetProperty("status").GetString());Assert.Equal("NOT_AVAILABLE",r.GetProperty("bankStatus").GetString());Assert.Equal(0,T(r,"netChange"));Assert.Empty(r.GetProperty("items").EnumerateArray());
 }
 [Fact] public async Task Trade_cash_is_operating_and_non_cash_expense_or_inventory_never_becomes_cash_flow()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();await Pay(c);var asset=await Account();var expense=await Account("EXPENSE");await Journal([new(expense,50),new(asset,Credit:50)]);var r=await Report(c);Assert.Equal("READY",r.GetProperty("status").GetString());Assert.Equal(-100,T(r,"operatingNet"));Assert.Equal(-100,T(r,"closingCash"));Assert.Equal(100,Activity(r,"OPERATING","outflow"));Assert.Equal(1,r.GetProperty("totalCount").GetInt64());Assert.Equal("RECONCILED",r.GetProperty("ledgerStatus").GetString());
 }
 [Fact] public async Task Investing_and_financing_split_includes_operating_GST_and_keeps_GL_unchanged()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var bank=await Bank(c);var asset=await Account();var j=await Journal([new(asset,110),new(bank,Credit:110)]);var detail=await Detail(c,j.Journal);var line=detail.GetProperty("lines")[0].GetProperty("journalLineId").GetGuid();var before=await S("SELECT count(*) FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company));Assert.Equal("INCOMPLETE",(await Report(c)).GetProperty("status").GetString());await Expect(await Classify(c,j.Journal,[new(line,"INVESTING",100),new(line,"OPERATING",10)]),HttpStatusCode.OK);var r=await Report(c);Assert.Equal(-100,T(r,"investingNet"));Assert.Equal(-10,T(r,"operatingNet"));Assert.Equal(-110,T(r,"netChange"));Assert.Equal(before,await S("SELECT count(*) FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company)));var equity=await Account("EQUITY");var funding=await Journal([new(bank,200),new(equity,Credit:200)]);var l=(await Detail(c,funding.Journal)).GetProperty("lines")[0].GetProperty("journalLineId").GetGuid();await Expect(await Classify(c,funding.Journal,[new(l,"FINANCING",200)]),HttpStatusCode.OK);r=await Report(c);Assert.Equal(200,T(r,"financingNet"));Assert.Equal(90,T(r,"closingCash"));Assert.Equal("READY",r.GetProperty("status").GetString());
 }
 [Fact] public async Task Pure_internal_transfers_are_excluded_from_operating_investing_and_financing_gross()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Bank(c);var b=await Bank(c);var j=await Journal([new(a,100),new(b,Credit:100)]);var cash=(await Detail(c,j.Journal)).GetProperty("lines").EnumerateArray().Select(x=>new CashFlowAllocation(x.GetProperty("journalLineId").GetGuid(),"OPERATING",100)).ToArray();await Expect(await Classify(c,j.Journal,cash),HttpStatusCode.UnprocessableEntity);var r=await Report(c);Assert.Equal(0,T(r,"classifiedNetChange"));Assert.Equal(0,T(r,"internalNet"));Assert.Equal(100,Activity(r,"INTERNAL","inflow"));Assert.Equal(100,Activity(r,"INTERNAL","outflow"));Assert.Equal(0,Activity(r,"OPERATING","outflow"));Assert.Equal("READY",r.GetProperty("status").GetString());
 }
 [Fact] public async Task Transfer_with_fee_requires_explicit_balanced_internal_split()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Bank(c);var b=await Bank(c);var expense=await Account("EXPENSE");var j=await Journal([new(a,Credit:105),new(b,100),new(expense,5)]);var rows=(await Detail(c,j.Journal)).GetProperty("lines").EnumerateArray().ToArray();var outId=rows.Single(x=>x.GetProperty("bankAccountId").GetGuid()==a).GetProperty("journalLineId").GetGuid();var inId=rows.Single(x=>x.GetProperty("bankAccountId").GetGuid()==b).GetProperty("journalLineId").GetGuid();await Expect(await Classify(c,j.Journal,[new(outId,"INTERNAL",100),new(outId,"OPERATING",5),new(inId,"INTERNAL",100)]),HttpStatusCode.OK);var r=await Report(c);Assert.Equal(-5,T(r,"operatingNet"));Assert.Equal(0,T(r,"internalNet"));Assert.Equal(5,Activity(r,"OPERATING","outflow"));Assert.Equal(100,Activity(r,"INTERNAL","inflow"));
 }
 [Fact] public async Task Unknown_opposite_cash_movements_do_not_look_complete_when_their_net_is_zero()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Bank(c);var contra=await Account();await Journal([new(a,10),new(contra,Credit:10)]);await Journal([new(a,Credit:10),new(contra,10)]);var r=await Report(c);Assert.Equal(0,T(r,"unclassifiedNet"));Assert.Equal(2,r.GetProperty("totals").GetProperty("unclassifiedCount").GetInt64());Assert.Equal("INCOMPLETE",r.GetProperty("status").GetString());Assert.Equal("RECONCILED",r.GetProperty("ledgerStatus").GetString());
 }
 [Fact] public async Task Classification_revisions_preserve_history_and_AUTO_resets_without_reposting()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.OK);await Expect(await Classify(c,p.Journal,[new(p.Cash,"INVESTING",100)],1),HttpStatusCode.OK);await Expect(await Classify(c,p.Journal,[],2,mode:"AUTO"),HttpStatusCode.OK);var d=await Detail(c,p.Journal);Assert.Equal(3,d.GetProperty("revision").GetInt64());Assert.Equal(3,d.GetProperty("history").GetArrayLength());Assert.Equal("FINANCING",d.GetProperty("history")[0].GetProperty("allocations")[0].GetProperty("category").GetString());Assert.Equal(-100,T(await Report(c),"operatingNet"));
 }
 [Fact] public async Task Reversal_inherits_original_split_and_reapplication_requires_review_after_custom_classification()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",90),new(p.Cash,"OPERATING",10)]),HttpStatusCode.OK);var reversal=await Expect(await Send(c,HttpMethod.Post,$"/supplier-payments/{p.Payment}/reverse",new SupplierSettlementReversalInput(Code(),"Wrong payment")),HttpStatusCode.Created);var r=await Report(c);Assert.Equal(0,Activity(r,"FINANCING","inflow"));Assert.Equal(0,Activity(r,"FINANCING","outflow"));Assert.Equal(0,T(r,"netChange"));var revId=reversal.GetProperty("reversal").GetProperty("id").GetGuid();var reapplied=await Expect(await Send(c,HttpMethod.Post,$"/supplier-payment-reversals/{revId}/reapply",new SupplierPaymentReapplicationInput(Code(),"Correct funds",100)),HttpStatusCode.Created);r=await Report(c);Assert.Equal("INCOMPLETE",r.GetProperty("status").GetString());Assert.Equal(-100,T(r,"unclassifiedNet"));
 }
 [Theory][InlineData("SALES")][InlineData("OFFICE")][InlineData("WAREHOUSE")][InlineData("PROCUREMENT")]
 public async Task Non_financial_roles_cannot_read_or_classify_cash_flow(string role)
 {
  await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await Pay(admin);var(subject,_)=await Staff(db,role);using var c=api.Authenticated(subject:subject);await Expect(await c.GetAsync($"/api/v1/accounting/reports/cash-flow?from={await Today():yyyy-MM-dd}&to={(await Today()).AddDays(1):yyyy-MM-dd}"),HttpStatusCode.Forbidden);await Expect(await c.GetAsync($"/api/v1/accounting/cash-flow/journals/{p.Journal}"),HttpStatusCode.Forbidden);await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.Forbidden);
 }
 [Fact] public async Task Company_scope_rejects_foreign_journals_cash_lines_and_scope_changes()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);using var other=api.Authenticated(company:db.OtherCompany);Assert.Equal(0,T(await Report(other),"closingCash"));await Expect(await other.GetAsync($"/api/v1/accounting/cash-flow/journals/{p.Journal}"),HttpStatusCode.NotFound);await Expect(await Classify(other,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.NotFound);var a=await Bank(c);await Expect(await Send(other,HttpMethod.Put,$"/accounting/cash-flow/scopes/{a}",new CashScopeInput(false,"Foreign scope"),1),HttpStatusCode.NotFound);
 }
 [Fact] public async Task Scope_is_configurable_before_use_and_frozen_after_first_posting()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var bank=await Bank(c);var scope=(await Get(c,"/accounting/cash-flow/scopes")).GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("bankAccountId").GetGuid()==bank);await Expect(await Send(c,HttpMethod.Put,$"/accounting/cash-flow/scopes/{bank}",new CashScopeInput(false,"Restricted deposit excluded"),scope.GetProperty("version").GetInt64()),HttpStatusCode.OK);await Pay(c,bank);var r=await Report(c);Assert.Equal(0,T(r,"closingCash"));Assert.Equal(-100,T(r,"allBankClosing"));Assert.Equal(-100,T(r,"excludedBankClosing"));Assert.Equal(0,T(r,"bankScopeDifference"));var current=(await Get(c,"/accounting/cash-flow/scopes")).GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("bankAccountId").GetGuid()==bank);await Expect(await Send(c,HttpMethod.Put,$"/accounting/cash-flow/scopes/{bank}",new CashScopeInput(true,"Cannot restate history"),current.GetProperty("version").GetInt64()),HttpStatusCode.Conflict);var ex=await Assert.ThrowsAsync<PostgresException>(()=>S("UPDATE accounting.cash_flow_scopes SET included=true WHERE company_id=@company AND bank_account_id=@bank",("company",db.Company),("bank",bank)));Assert.Equal("HR409",ex.SqlState);
 }
 [Fact] public async Task Card_clearing_is_excluded_and_inactive_cash_accounts_still_contribute_history()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var card=await Bank(c,"CARD_CLEARING");await Pay(c,card);var input=new BankAccountInput(Code(),"Till","CASH");var b=await Expect(await Send(c,HttpMethod.Post,"/bank-accounts",input),HttpStatusCode.Created);await Pay(c,Id(b),20);await Expect(await Send(c,HttpMethod.Put,$"/bank-accounts/{Id(b)}",input with{Active=false},b.GetProperty("version").GetInt64()),HttpStatusCode.OK);var r=await Report(c);Assert.Equal(-20,T(r,"closingCash"));Assert.Equal(-100,T(r,"excludedBankClosing"));Assert.Equal(-120,T(r,"allBankClosing"));
 }
 [Fact] public async Task Concurrent_same_key_classification_has_one_fact_and_different_keys_obey_revision()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var key=Code();var items=new CashFlowAllocation[]{new(p.Cash,"INVESTING",100)};var all=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>Classify(c,p.Journal,items,key:key)));foreach(var response in all)await Expect(response,HttpStatusCode.OK);Assert.Equal(1,(await Detail(c,p.Journal)).GetProperty("history").GetArrayLength());var race=await Task.WhenAll(Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)],1),Classify(c,p.Journal,[new(p.Cash,"OPERATING",100)],1));await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)],key:key),HttpStatusCode.Conflict);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);
 }
 [Theory][InlineData("under")][InlineData("over")][InlineData("unknown")][InlineData("other_journal")][InlineData("precision")][InlineData("zero")][InlineData("negative")][InlineData("duplicate")][InlineData("category")][InlineData("empty")][InlineData("internal_unpaired")][InlineData("auto_with_items")]
 public async Task Invalid_allocations_are_atomic_and_do_not_consume_revision(string scenario)
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var item=new CashFlowAllocation(p.Cash,"INVESTING",100);item=scenario switch{"under"=>item with{Amount=99},"over"=>item with{Amount=101},"unknown"=>item with{JournalLineId=Guid.NewGuid()},"other_journal"=>item with{JournalLineId=(await Pay(c)).Cash},"precision"=>item with{Amount=99.999m},"zero"=>item with{Amount=0},"negative"=>item with{Amount=-100},"category"=>item with{Category="OTHER"},"internal_unpaired"=>item with{Category="INTERNAL"},_=>item};var items=scenario=="empty"?Array.Empty<CashFlowAllocation>():scenario=="duplicate"?[item,item]:new[]{item};using var response=await Classify(c,p.Journal,items,mode:scenario=="auto_with_items"?"AUTO":"CUSTOM");Assert.Contains(response.StatusCode,new[]{HttpStatusCode.BadRequest,HttpStatusCode.UnprocessableEntity});Assert.Equal(0,(await Detail(c,p.Journal)).GetProperty("revision").GetInt64());
 }
 [Fact] public async Task Reversal_cannot_be_manually_reclassified_independently_of_original()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var response=await Expect(await Send(c,HttpMethod.Post,$"/supplier-payments/{p.Payment}/reverse",new SupplierSettlementReversalInput(Code(),"Correction")),HttpStatusCode.Created);var reversal=response.GetProperty("reversal").GetProperty("id").GetGuid();var journal=(Guid)(await S("SELECT journal_entry_id FROM accounting.supplier_payment_reversals WHERE company_id=@company AND id=@id",("company",db.Company),("id",reversal)))!;var line=(await Detail(c,journal)).GetProperty("lines")[0].GetProperty("journalLineId").GetGuid();await Expect(await Classify(c,journal,[new(line,"FINANCING",100)]),HttpStatusCode.Conflict);await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.OK);var r=await Report(c);Assert.Equal(0,Activity(r,"FINANCING","inflow"));Assert.Equal(0,Activity(r,"FINANCING","outflow"));Assert.Equal(0,T(r,"netChange"));
 }
 [Fact] public async Task Late_audit_failure_rolls_back_classification_and_idempotency_then_same_key_retries()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var key=Code();await S($"CREATE FUNCTION accounting.test_cash_flow_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.company_id='{db.Company}'::uuid AND NEW.action='accounting.cash_flow_classified' THEN RAISE EXCEPTION 'Injected classification audit failure' USING ERRCODE='HR422';END IF;RETURN NEW;END $$;CREATE TRIGGER test_cash_flow_audit_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_cash_flow_audit_failure()");try{await Expect(await Classify(c,p.Journal,[new(p.Cash,"INVESTING",100)],key:key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0,(await Detail(c,p.Journal)).GetProperty("revision").GetInt64());Assert.Equal(-100,T(await Report(c),"operatingNet"));}finally{await S("DROP TRIGGER test_cash_flow_audit_failure ON platform.audit_events;DROP FUNCTION accounting.test_cash_flow_audit_failure()");}await Expect(await Classify(c,p.Journal,[new(p.Cash,"INVESTING",100)],key:key),HttpStatusCode.OK);Assert.Equal(-100,T(await Report(c),"investingNet"));
 }
 [Theory][InlineData("accounting.reports.read")][InlineData("accounting.ledger.read")][InlineData("accounting.banks.read")][InlineData("accounting.cash_flow.classify")]
 public async Task Revoked_permissions_block_cached_mutation_results(string permission)
