 [Fact] public async Task Concurrent_reclassification_has_one_complete_read_snapshot()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);await using var session=await db.SessionAsync();await Sql.RowsAsync(session,"SELECT accounting.classify_cash_flow(@journal,0,'CUSTOM','Reviewed investing purchase',jsonb_build_array(jsonb_build_object('journalLineId',@line,'category','INVESTING','amount',100))) AS id",default,("journal",p.Journal),("line",p.Cash));var first=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var reader=Task.Run(async()=>{var result=new List<JsonElement>();for(var i=0;i<18;i++){result.Add(await Report(c));if(i==0)first.SetResult();await Task.Delay(3);}return result;});var gate=await Task.WhenAny(first.Task,reader);if(gate==reader)await reader;await first.Task.WaitAsync(TimeSpan.FromSeconds(20));await session.Transaction.CommitAsync();var reports=await reader;Assert.Contains(reports,x=>T(x,"operatingNet")==-100);Assert.Contains(reports,x=>T(x,"investingNet")==-100);Assert.All(reports,x=>{Assert.Equal(-100,T(x,"operatingNet")+T(x,"investingNet"));Assert.Equal(-100,T(x,"closingCash"));Assert.Equal("RECONCILED",x.GetProperty("ledgerStatus").GetString());Assert.Equal(T(x,"classifiedNetChange"),x.GetProperty("items").EnumerateArray().Sum(i=>D(i.GetProperty("signedAmount"))));});
 }
 [Theory][InlineData(true)][InlineData(false)]
 public async Task Scope_change_and_cash_posting_are_serialized_in_both_orders(bool scopeFirst)
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var bank=await Bank(c);var scope=(await Get(c,"/accounting/cash-flow/scopes")).GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("bankAccountId").GetGuid()==bank);var version=scope.GetProperty("version").GetInt64();var supplier=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Concurrent supplier",null));await using var session=await db.SessionAsync();
  if(scopeFirst)await Sql.RowsAsync(session,"SELECT accounting.configure_cash_scope(@bank,@version,false,'Excluded before use')",default,("bank",bank),("version",version));
  else await Sql.RowsAsync(session,"SELECT purchase.post_supplier_payment_to_bank(@supplier,100,100,'BANK_TRANSFER',@reference,NULL,'Trade deposit','[]'::jsonb,@bank) AS id",default,("supplier",supplier),("reference",Code()),("bank",bank));
  Task<HttpResponseMessage> pending=scopeFirst?Send(c,HttpMethod.Post,$"/suppliers/{supplier}/payments",new SupplierPaymentInput(100,"BANK_TRANSFER",Code(),100,Notes:"Trade deposit",BankAccountId:bank)):Send(c,HttpMethod.Put,$"/accounting/cash-flow/scopes/{bank}",new CashScopeInput(false,"Concurrent exclusion"),version);
  var blocked=false;for(var i=0;i<40;i++){blocked=Convert.ToBoolean(await S("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE @pid=ANY(pg_blocking_pids(pid)))",("pid",session.Connection.ProcessID)));if(blocked)break;await Task.Delay(20);}Assert.True(blocked);await session.Transaction.CommitAsync();await Expect(await pending,scopeFirst?HttpStatusCode.Created:HttpStatusCode.Conflict);var r=await Report(c);Assert.Equal(scopeFirst?0:-100,T(r,"closingCash"));Assert.Equal(-100,T(r,"allBankClosing"));Assert.Equal("RECONCILED",r.GetProperty("ledgerStatus").GetString());
 }
 [Fact] public async Task Bank_reconciliation_uses_outstanding_adjustment_and_is_not_counted_as_new_cash()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var bank=await Bank(c,"BANK");var p=await Pay(c,bank);await Pay(c,bank,20);var date=await Today();var imported=await Expect(await Send(c,HttpMethod.Post,$"/bank-accounts/{bank}/statements/import",new BankStatementImportInput(Code(),date,date,0,-100,[new(date,-100,"Bank debit",Code(),Code())])),HttpStatusCode.Created);var sid=imported.GetProperty("statement").GetProperty("id").GetGuid();var line=imported.GetProperty("lines")[0].GetProperty("id").GetGuid();var matched=await Expect(await Send(c,HttpMethod.Post,$"/bank-statement-lines/{line}/matches",new BankMatchInput(Code(),"Verified payment",[new(p.Cash,100)]),imported.GetProperty("statement").GetProperty("version").GetInt64()),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/bank-statements/{sid}/reconcile",new BankReconcileInput(Code(),"Bank checked"),matched.GetProperty("statement").GetProperty("statement").GetProperty("version").GetInt64()),HttpStatusCode.Created);var r=await Report(c);Assert.Equal("RECONCILED",r.GetProperty("bankStatus").GetString());Assert.Equal(-120,T(r,"closingCash"));Assert.Equal(-120,T(r,"operatingNet"));var row=r.GetProperty("banks").EnumerateArray().Single(x=>x.GetProperty("bankAccountId").GetGuid()==bank);Assert.Equal(-100,D(row.GetProperty("statementClosing")));Assert.Equal(20,D(row.GetProperty("outstandingPayments")));Assert.Equal(0,D(row.GetProperty("reconciliationDifference")));Assert.Equal("PARTIAL",(await Report(c,to:date.AddDays(2))).GetProperty("bankStatus").GetString());var other=await Bank(c,"BANK");await Pay(c,other,10);Assert.Equal("PARTIAL",(await Report(c)).GetProperty("bankStatus").GetString());
 }
 [Fact] public async Task Period_opening_closing_and_pagination_use_all_cash_entries()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var today=await Today();await Pay(c,amount:100,date:today.AddDays(-1));await Pay(c,amount:20);var r=await Report(c,suffix:"&pageSize=1");Assert.Equal(-100,T(r,"openingCash"));Assert.Equal(-20,T(r,"operatingNet"));Assert.Equal(-120,T(r,"closingCash"));var prior=await Report(c,today.AddDays(-1),today);Assert.Equal(-100,T(prior,"operatingNet"));await Pay(c,amount:30);r=await Report(c,suffix:"&pageSize=1");Assert.Equal(2,r.GetProperty("totalCount").GetInt64());Assert.Single(r.GetProperty("items").EnumerateArray());var second=await Report(c,suffix:"&pageSize=1&page=2");Assert.Equal(-150,T(second,"closingCash"));Assert.Equal(T(r,"netChange"),T(second,"netChange"));Assert.NotEqual(r.GetProperty("items")[0].GetProperty("journalId").GetGuid(),second.GetProperty("items")[0].GetProperty("journalId").GetGuid());
 }
 [Fact] public async Task App_cannot_write_classification_facts_and_owner_cannot_mutate_history()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var result=await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.OK);await using(var session=await db.SessionAsync()){var error=await Assert.ThrowsAsync<PostgresException>(()=>Sql.RowsAsync(session,"UPDATE accounting.cash_flow_scopes SET included=false WHERE company_id=core.current_company()",default));Assert.Equal("42501",error.SqlState);}var ex=await Assert.ThrowsAsync<PostgresException>(()=>S("UPDATE accounting.cash_flow_classifications SET reason='Changed' WHERE company_id=@company AND id=@id",("company",db.Company),("id",Id(result))));Assert.Equal("23514",ex.SqlState);
 }

 [Theory][InlineData("from=2026-01-01&to=2026-01-01")][InlineData("from=2025-01-01&to=2026-01-03")][InlineData("from=0001-01-01&to=0001-01-02")][InlineData("to=2026-01-02")]
 public async Task Invalid_periods_are_rejected_without_server_errors(string query)
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();using var response=await c.GetAsync("/api/v1/accounting/reports/cash-flow?"+query);Assert.Contains(response.StatusCode,new[]{HttpStatusCode.BadRequest,HttpStatusCode.UnprocessableEntity});
 }
 [Fact] public async Task Finance_has_explicit_report_classification_and_scope_permissions()
 {
  await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await Pay(admin);var bank=await Bank(admin);var(subject,_)=await Staff(db,"FINANCE");using var c=api.Authenticated(subject:subject);Assert.Equal(-100,T(await Report(c),"operatingNet"));await Expect(await Classify(c,p.Journal,[new(p.Cash,"FINANCING",100)]),HttpStatusCode.OK);var scope=(await Get(c,"/accounting/cash-flow/scopes")).GetProperty("items").EnumerateArray().Single(x=>x.GetProperty("bankAccountId").GetGuid()==bank);await Expect(await Send(c,HttpMethod.Put,$"/accounting/cash-flow/scopes/{bank}",new CashScopeInput(false,"Restricted investment account"),scope.GetProperty("version").GetInt64()),HttpStatusCode.OK);
 }

 [Fact] public async Task Real_supplier_refund_is_cash_inflow_while_its_book_reversal_reduces_inflow()
 {
  await using var api=new TestApi(db);using var c=api.Authenticated();var p=await Pay(c);var advance=(Guid)(await S("SELECT id FROM accounting.supplier_advances WHERE company_id=@company AND payment_id=@id",("company",db.Company),("id",p.Payment)))!;
  var refund=await Expect(await Send(c,HttpMethod.Post,"/supplier-refunds",new SupplierRefundInput(20,Code(),"Actual returned funds",AdvanceId:advance)),HttpStatusCode.Created);Assert.Equal(20,Activity(await Report(c),"OPERATING","inflow"));
  var reversal=await Expect(await Send(c,HttpMethod.Post,$"/supplier-refunds/{refund.GetProperty("refund").GetProperty("id").GetGuid()}/reverse",new SupplierRefundReversalInput(Code(),"Recorded refund amount was wrong")),HttpStatusCode.Created);var r=await Report(c);Assert.Equal(0,Activity(r,"OPERATING","inflow"));Assert.Equal(100,Activity(r,"OPERATING","outflow"));Assert.Equal(-100,T(r,"closingCash"));
  await Expect(await Send(c,HttpMethod.Post,$"/supplier-refund-reversals/{reversal.GetProperty("reversal").GetProperty("id").GetGuid()}/correct",new SupplierRefundCorrectionInput(Code(),"Correct actual amount",5,AdvanceId:advance)),HttpStatusCode.Created);r=await Report(c);Assert.Equal(5,Activity(r,"OPERATING","inflow"));Assert.Equal(100,Activity(r,"OPERATING","outflow"));Assert.Equal(-95,T(r,"operatingNet"));Assert.Equal("RECONCILED",r.GetProperty("ledgerStatus").GetString());
 }
